#include <stdio.h>

int main(void) {
    int a = 12; // 0000 1100
    int b = 10; // 0000 1010

    printf("a & b: %d\n", a & b);   // 0000 1000 -> 8
    printf("a | b: %d\n", a | b);   // 0000 1110 -> 14
    printf("a ^ b: %d\n", a ^ b);   // 0000 0110 -> 6 (XOR)
    printf("a << 1: %d\n", a << 1); // 0001 1000 -> 24 (2배)

    // 삼항 조건 연산자
    int max = (a > b) ? a : b;
    printf("Max: %d\n", max);
    return 0;
}

