#include <stdio.h>

int main(void) {
    // 1. for 문: 정해진 횟수 누적
    int sum = 0;
    for (int i = 1; i <= 5; i++) {
        sum += i;
    }
    printf("1~5 Sum: %d\n", sum);

    // 2. while 문: 특정 조건까지
    int count = 3;
    while (count > 0) {
        printf("Countdown: %d\n", count);
        count--;
    }

    // 3. break & continue
    for (int i = 0; i < 10; i++) {
        if (i % 2 == 0) continue; // 짝수 스킵
        if (i > 5) break;         // 5 초과 시 즉시 탈출
        printf("Odd: %d\n", i);
    }
    return 0;
}

